func (this *Deribit) HandleTrades(client any, message map[string]any) {
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "trades.BTC_USDC-PERPETUAL.100ms",
	//             "data": [{
	//                 "trade_seq": 501899,
	//                 "trade_id": "USDC-2436803",
	//                 "timestamp": 1655397355998,
	//                 "tick_direction": 2,
	//                 "price": 21026,
	//                 "mark_price": 21019.9719,
	//                 "instrument_name": "BTC_USDC-PERPETUAL",
	//                 "index_price": 21031.7847,
	//                 "direction": "buy",
	//                 "amount": 0.049
	//             }]
	//         }
	//     }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var channel *string = this.SafeString(params, "channel", "")
	var parts []string = strings.Split(*channel, ".")
	var marketId *string = this.SafeString(parts, 1)
	var interval *string = this.SafeString(parts, 2)
	var symbol *string = this.SafeSymbol(marketId)
	var market map[string]any = this.SafeMarket(marketId)
	var trades []any = ccxt.SafeListTyped(params, "data")
	if ccxt.IsEqual(this.SafeDict(this.Trades, symbol), nil) {
		var limit *int64 = this.SafeInteger(this.Options, "tradesLimit", 1000)
		ccxt.AddElementToObject(this.Trades, symbol, ccxt.NewArrayCache(limit))
	}
	var stored any = ccxt.GetValue(this.Trades, symbol)
	for i := 0; i < len(trades); i++ {
		var trade any = func() any {
			if i >= 0 && i < len(trades) {
				return ccxt.DerefScalar(trades[i])
			}
			return nil
		}()
		var parsed map[string]any = ccxt.MapTyped(this.ParseTrade(trade, market))
		stored.(ccxt.Appender).Append(parsed)
	}
	ccxt.AddElementToObject(this.Trades, symbol, stored)
	var messageHash *string = ccxt.SafeStringPtr(ccxt.Add("trades|"+*symbol+"|", interval))
	client.(ccxt.ClientInterface).Resolve(ccxt.GetValue(this.Trades, symbol), messageHash)
}

