/**
 * @method
 * @name deribit#watchOrderBookForSymbols
 * @description watches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://docs.deribit.com/#book-instrument_name-group-depth-interval
 * @param {string[]} symbols unified array of symbols
 * @param {int} [limit] the maximum amount of order book entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Deribit) WatchOrderBookForSymbolsAsync(symbols any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrderBookForSymbolsBody(ch, symbols, optionalArgs...)
	return ch
}
func (this *Deribit) watchOrderBookForSymbolsBody(ch chan any, symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	interval, paramsInterval := this.HandleOptionStringAndParams(params, "watchOrderBookForSymbols", "interval", "100ms")
	if interval != nil && *interval == "raw" {

		ccxt.PanicOnError((<-this.AuthenticateAsync()))
	}
	// for more info on useDepthEndpoint, see comment in .options
	useDepthEndpoint, paramsUseDepthEndpoint := this.HandleOptionBoolAndParams(paramsInterval, "watchOrderBookForSymbols", "useDepthEndpoint", false)
	depth, paramsDepth := this.HandleOptionStringAndParams(paramsUseDepthEndpoint, "watchOrderBookForSymbols", "depth", "20")
	group, paramsGroup := this.HandleOptionStringAndParams(paramsDepth, "watchOrderBookForSymbols", "group", "none")
	var descriptor any = interval
	if useDepthEndpoint {
		descriptor = ccxt.Add(*group+"."+*depth+".", interval)
	}
	var paramsResolved any = paramsUseDepthEndpoint
	if useDepthEndpoint {
		paramsResolved = paramsGroup
	}

	var orderbook ccxt.OrderBookInterface = ccxt.PanicOnError((<-this.WatchMultipleWrapperAsync("book", descriptor, symbols, paramsResolved))).(ccxt.OrderBookInterface)

	ch <- orderbook.(ccxt.OrderBookInterface).Limit()
	return nil
}
func (this *Deribit) HandleOrderBook(client any, message map[string]any) {
	//
	//  snapshot
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "book.BTC_USDC-PERPETUAL.raw",
	//             "data": {
	//                 "type": "snapshot",
	//                 "timestamp": 1655395057025,
	//                 "instrument_name": "BTC_USDC-PERPETUAL",
	//                 "change_id": 1550694837,
	//                 "bids": [
	//                     ["new", 20987, 0.487],
	//                     ["new", 20986, 0.238],
	//                 ],
	//                 "asks": [
	//                     ["new", 20999, 0.092],
	//                     ["new", 21000, 1.238],
	//                 ]
	//             }
	//         }
	//     }
	//
	//  change
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "book.BTC_USDC-PERPETUAL.raw",
	//             "data": {
	//                 "type": "change",
	//                 "timestamp": 1655395168086,
	//                 "prev_change_id": 1550724481,
	//                 "instrument_name": "BTC_USDC-PERPETUAL",
	//                 "change_id": 1550724483,
	//                 "bids": [
	//                     ["new", 20977, 0.109],
	//                     ["delete", 20975, 0]
	//                 ],
	//                 "asks": []
	//             }
	//         }
	//     }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var data map[string]any = ccxt.SafeMapTyped(params, "data")
	var channel *string = this.SafeString(params, "channel")
	var parts []string = ccxt.Split(channel, ".")
	var descriptor any = ""
	var partsLength int = len(parts)
	var isDetailed bool = (partsLength == 5)
	if isDetailed {
		var group *string = this.SafeString(parts, 2)
		var depth *string = this.SafeString(parts, 3)
		var interval *string = this.SafeString(parts, 4)
		descriptor = ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(group, "."), depth), "."), interval)
	} else {
		var interval *string = this.SafeString(parts, 2)
		descriptor = interval
	}
	var marketId *string = this.SafeString(data, "instrument_name")
	var symbol *string = this.SafeSymbol(marketId)
	var timestamp *int64 = this.SafeInteger(data, "timestamp")
	if !(ccxt.InOp(this.Orderbooks, symbol)) {
		ccxt.AddElementToObject(this.Orderbooks, symbol, this.CountedOrderBook())
	}
	var storedOrderBook any = ccxt.GetValue(this.Orderbooks, symbol)
	var asks []any = ccxt.SafeListTypedDefault(data, "asks", []any{})
	var bids []any = ccxt.SafeListTypedDefault(data, "bids", []any{})
	this.HandleDeltas(ccxt.GetValue(storedOrderBook, "asks"), asks)
	this.HandleDeltas(ccxt.GetValue(storedOrderBook, "bids"), bids)
	ccxt.AddElementToObject(storedOrderBook, "nonce", timestamp)
	ccxt.AddElementToObject(storedOrderBook, "timestamp", timestamp)
	ccxt.AddElementToObject(storedOrderBook, "datetime", this.Iso8601(timestamp))
	ccxt.AddElementToObject(storedOrderBook, "symbol", symbol)
	ccxt.AddElementToObject(this.Orderbooks, symbol, storedOrderBook)
	var messageHash *string = ccxt.SafeStringPtr(ccxt.Add("book|"+*symbol+"|", descriptor))
	client.(ccxt.ClientInterface).Resolve(storedOrderBook, messageHash)
}
func (this *Deribit) CleanOrderBook(data any) any {
	var bids []any = ccxt.SafeListTyped(data, "bids")
	var asks []any = ccxt.SafeListTyped(data, "asks")
	var cleanedBids []any = []any{}
	for i := 0; i < len(bids); i++ {
		cleanedBids = append(cleanedBids, []any{ccxt.GetValue(func() any {
			if i >= 0 && i < len(bids) {
				return ccxt.DerefScalar(bids[i])
			}
			return nil
		}(), 1), ccxt.GetValue(func() any {
			if i >= 0 && i < len(bids) {
				return ccxt.DerefScalar(bids[i])
			}
			return nil
		}(), 2)})
	}
	var cleanedAsks []any = []any{}
	for i := 0; i < len(asks); i++ {
		cleanedAsks = append(cleanedAsks, []any{ccxt.GetValue(func() any {
			if i >= 0 && i < len(asks) {
				return ccxt.DerefScalar(asks[i])
			}
			return nil
		}(), 1), ccxt.GetValue(func() any {
			if i >= 0 && i < len(asks) {
				return ccxt.DerefScalar(asks[i])
			}
			return nil
		}(), 2)})
	}
	ccxt.AddElementToObject(data, "bids", cleanedBids)
	ccxt.AddElementToObject(data, "asks", cleanedAsks)
	return data
}
func (this *Deribit) HandleDelta(bookside any, delta any) {
	var price any = ccxt.GetValue(delta, 1)
	var amount any = ccxt.GetValue(delta, 2)
	var action *string = this.SafeString(delta, 0)
	if (action != nil && *action == "new") || (action != nil && *action == "change") {
		bookside.(ccxt.IOrderBookSide).StoreArray([]any{price, amount, 1})
	} else if action != nil && *action == "delete" {
		bookside.(ccxt.IOrderBookSide).StoreArray([]any{price, amount, 0})
	}
}
func (this *Deribit) HandleDeltas(bookside any, deltas any) {
	for i := 0; i < ccxt.GetArrayLength(deltas); i++ {
		this.HandleDelta(bookside, ccxt.GetValue(deltas, i))
	}
}

/**
 * @method
 * @name deribit#watchOrders
 * @see https://docs.deribit.com/#user-orders-instrument_name-raw
 * @description watches information on multiple orders made by the user
 * @param {string} symbol unified market symbol of the market orders were made in
 * @param {int} [since] the earliest time in ms to fetch orders for
 * @param {int} [limit] the maximum number of order structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Deribit) WatchOrdersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrdersBody(ch, optionalArgs...)
	return ch
}
func (this *Deribit) watchOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var symbol *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}

	ccxt.PanicOnError((<-this.AuthenticateAsync(params)))
	var symbolResolved any = func() any {
		if symbol != nil {
			return this.Symbol(symbol)
		}
		return nil
	}()
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"))
	var currency *string = this.SafeString(params, "currency", "any")
	var interval *string = this.SafeString(params, "interval", "raw")
	var kind *string = this.SafeString(params, "kind", "any")
	var paramsOmitted map[string]any = this.OmitDict(params, "interval", "currency", "kind")
	var channel string = "user.orders." + *kind + "." + *currency + "." + *interval
	var message map[string]any = map[string]any{
		"jsonrpc": "2.0",
		"method":  "private/subscribe",
		"params": map[string]any{
			"channels": []any{channel},
		},
		"id": this.RequestId(),
	}
	var request map[string]any = this.DeepExtend(message, paramsOmitted)

	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(ccxt.PanicOnError((<-this.Watch(url, channel, request, channel, request))))
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(orders).GetLimit(symbolResolved, limit)
	}

	ch <- this.FilterBySymbolSinceLimit(orders, symbolResolved, since, limitResolved, true)
	return nil
}
func (this *Deribit) HandleOrders(client any, message map[string]any) {
	// Does not return a snapshot of current orders
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "user.orders.any.any.raw",
	//             "data": {
	//                 "web": true,
	//                 "time_in_force": "good_til_cancelled",
	//                 "replaced": false,
	//                 "reduce_only": false,
	//                 "profit_loss": 0,
	//                 "price": 50000,
	//                 "post_only": false,
	//                 "order_type": "limit",
	//                 "order_state": "open",
	//                 "order_id": "46094375191",
	//                 "max_show": 10,
	//                 "last_update_timestamp": 1655401625037,
	//                 "label": '',
	//                 "is_liquidation": false,
	//                 "instrument_name": "BTC-PERPETUAL",
	//                 "filled_amount": 0,
	//                 "direction": "sell",
	//                 "creation_timestamp": 1655401625037,
	//                 "commission": 0,
	//                 "average_price": 0,
	//                 "api": false,
	//                 "amount": 10
	//             }
	//         }
	//     }
	//
	if this.Orders == nil {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var channel *string = this.SafeString(params, "channel", "")
	var data any = this.SafeValue(params, "data", map[string]any{})
	var orders any = []any{}
	if ccxt.IsArray(data) {
		orders = this.ParseOrders(data)
	} else {
		var order map[string]any = ccxt.MapTyped(this.ParseOrder(data))
		orders = []any{order}
	}
	var cachedOrders any = this.Orders
	for i := 0; i < ccxt.GetArrayLength(orders); i++ {
		cachedOrders.(ccxt.Appender).Append(ccxt.GetValue(orders, i))
	}
	client.(ccxt.ClientInterface).Resolve(this.Orders, channel)
}

/**
 * @method
 * @name deribit#watchOHLCV
 * @see https://docs.deribit.com/#chart-trades-instrument_name-resolution
 * @description watches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @param {string} symbol unified symbol of the market to fetch ccxt.OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Deribit) WatchOHLCVAsync(symbol string, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Deribit) watchOHLCVBody(ch chan any, symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var timeframe string = ccxt.GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var symbolValue any = this.Symbol(symbol)

	var ohlcvs map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.WatchOHLCVForSymbolsAsync([]any{[]any{symbolValue, timeframe}}, since, limit, params))))

	ch <- ccxt.GetValue(ccxt.GetValue(ohlcvs, symbolValue), timeframe)
	return nil
}

/**
 * @method
 * @name deribit#watchOHLCVForSymbols
 * @description watches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://docs.deribit.com/#chart-trades-instrument_name-resolution
 * @param {string[][]} symbolsAndTimeframes array of arrays containing unified symbols and timeframes to fetch ccxt.OHLCV data for, example [['BTC/USDT', '1m'], ['LTC/USDT', '5m']]
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Deribit) WatchOHLCVForSymbolsAsync(symbolsAndTimeframes any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOHLCVForSymbolsBody(ch, symbolsAndTimeframes, optionalArgs...)
	return ch
}
func (this *Deribit) watchOHLCVForSymbolsBody(ch chan any, symbolsAndTimeframes any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	var symbolsLength int = ccxt.GetArrayLength(symbolsAndTimeframes)
	if (symbolsLength == 0) || !ccxt.IsArray(ccxt.GetValue(symbolsAndTimeframes, 0)) {
		panic(ccxt.ArgumentsRequired(this.Id + " watchOHLCVForSymbols() requires a an array of symbols and timeframes, like  [['BTC/USDT', '1m'], ['LTC/USDT', '5m']]"))
	}
	symboltimeframecandlesVariable := (<-this.WatchMultipleWrapperAsync("chart.trades", nil, symbolsAndTimeframes, params))
	symbol := ccxt.GetValue(symboltimeframecandlesVariable, 0)
	timeframe := ccxt.GetValue(symboltimeframecandlesVariable, 1)
	candles := ccxt.GetValue(symboltimeframecandlesVariable, 2)
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(candles).GetLimit(symbol, limit)
	}
	var filtered any = this.FilterBySinceLimit(candles, since, limitResolved, 0, true)

	ch <- this.CreateOHLCVObject(symbol, timeframe, filtered)
	return nil
}
func (this *Deribit) HandleOHLCV(client any, message map[string]any) {
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "chart.trades.BTC_USDC-PERPETUAL.1",
	//             "data": {
	//                 "volume": 0,
	//                 "tick": 1655403420000,
	//                 "open": 20951,
	//                 "low": 20951,
	//                 "high": 20951,
	//                 "cost": 0,
	//                 "close": 20951
	//             }
	//         }
	//     }
	//
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var channel *string = this.SafeString(params, "channel", "")
	var parts []string = strings.Split(*channel, ".")
	var marketId *string = this.SafeString(parts, 2)
	var rawTimeframe *string = this.SafeString(parts, 3)
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var wsOptions map[string]any = ccxt.SafeMapTyped(this.Options, "ws")
	var timeframes any = this.SafeDict(wsOptions, "timeframes", map[string]any{})
	var unifiedTimeframe *string = this.FindTimeframe(rawTimeframe, timeframes)
	ccxt.AddElementToObject(this.Ohlcvs, symbol, this.SafeDict(this.Ohlcvs, symbol, map[string]any{}))
	if ccxt.IsEqual(this.SafeDict(ccxt.GetValue(this.Ohlcvs, symbol), unifiedTimeframe), nil) {
		var limit *int64 = this.SafeInteger(this.Options, "OHLCVLimit", 1000)
		ccxt.AddElementToObject(ccxt.GetValue(this.Ohlcvs, symbol), unifiedTimeframe, ccxt.NewArrayCacheByTimestamp(limit))
	}
	var stored any = ccxt.GetValue(ccxt.GetValue(this.Ohlcvs, symbol), unifiedTimeframe)
	var ohlcv map[string]any = this.SafeDictMap(params, "data", map[string]any{})
	// data contains a single ccxt.OHLCV candle
	var parsed any = this.ParseWsOHLCV(ohlcv, market)
	stored.(ccxt.Appender).Append(parsed)
	ccxt.AddElementToObject(ccxt.GetValue(this.Ohlcvs, symbol), unifiedTimeframe, stored)
	var resolveData []any = []any{symbol, unifiedTimeframe, stored}
	var messageHash *string = ccxt.SafeStringPtr(ccxt.Add("chart.trades|"+*symbol+"|", rawTimeframe))
	client.(ccxt.ClientInterface).Resolve(resolveData, messageHash)
}
func (this *Deribit) ParseWsOHLCV(ohlcv any, optionalArgs ...any) any {
	//
	//    {
	//        "c": "28909.0",
	//        "o": "28915.4",
	//        "h": "28915.4",
	//        "l": "28896.1",
	//        "v": "27.6919",
	//        "T": 1696687499999,
	//        "t": 1696687440000
	//    }
	//
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	return []any{this.SafeInteger(ohlcv, "tick"), this.SafeNumber(ohlcv, "open"), this.SafeNumber(ohlcv, "high"), this.SafeNumber(ohlcv, "low"), this.SafeNumber(ohlcv, "close"), this.SafeNumber(ohlcv, "volume")}
}
func (this *Deribit) WatchMultipleWrapperAsync(channelName string, channelDescriptor any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchMultipleWrapperBody(ch, channelName, channelDescriptor, optionalArgs...)
	return ch
}
func (this *Deribit) watchMultipleWrapperBody(ch chan any, channelName string, channelDescriptor any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbolsArray := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbolsArray
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets == nil {

		ccxt.PanicOnError((<-this.LoadMarketsAsync()))
	}
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"))
	var rawSubscriptions []any = []any{}
	var messageHashes []any = []any{}
	var isOHLCV bool = (channelName == "chart.trades")
	var symbols any = func() any {
		if isOHLCV {
			return this.GetListFromObjectValues(symbolsArray, 0)
		}
		return symbolsArray
	}()
	this.MarketSymbols(symbols, nil, false)
	if ccxt.IsEqual(symbolsArray, nil) {
		panic(ccxt.ArgumentsRequired(this.Id + " watchMultipleWrapper() symbolsArray is required"))
	}
	for i := 0; i < ccxt.GetArrayLength(symbolsArray); i++ {
		if ccxt.IsEqual(symbolsArray, nil) {
			panic(ccxt.ArgumentsRequired(this.Id + " watchMultipleWrapper() symbolsArray is required"))
		}
		var current any = ccxt.GetValue(symbolsArray, i)
		var market map[string]any = nil
		var currentDescriptor any = nil
		if isOHLCV {
			market = this.Market(ccxt.GetValue(current, 0))
			var unifiedTf any = ccxt.GetValue(current, 1)
			currentDescriptor = this.SafeString(this.Timeframes, unifiedTf, unifiedTf)
		} else {
			market = this.Market(current)
			currentDescriptor = channelDescriptor
		}
		var message *string = ccxt.SafeStringPtr(ccxt.Add(ccxt.Add(ccxt.Add(channelName+".", market["id"]), "."), currentDescriptor))
		rawSubscriptions = append(rawSubscriptions, message)
		messageHashes = append(messageHashes, ccxt.Add(ccxt.Add(ccxt.Add(channelName+"|", market["symbol"]), "|"), currentDescriptor))
	}
	var request map[string]any = map[string]any{
		"jsonrpc": "2.0",
		"method":  "public/subscribe",
		"params": map[string]any{
			"channels": rawSubscriptions,
		},
		"id": this.RequestId(),
	}
	var extendedRequest map[string]any = this.DeepExtend(request, params)
	var maxMessageByteLimit int64 = ccxt.Subtract(32768, 1).(int64) // 'Message Too Big: limit 32768B'
	var jsonedText string = this.Json(extendedRequest)
	if ccxt.IsGreaterThanOrEqual(len(jsonedText), maxMessageByteLimit) {
		panic(ccxt.ExchangeError(this.Id + " requested subscription length over limit, try to reduce symbols amount"))
	}

	ch <- ccxt.PanicOnError((<-this.WatchMultiple(url, messageHashes, extendedRequest, rawSubscriptions)))
	return nil
}
func (this *Deribit) HandleMessage(client any, message any) {
	//
	// error
	//     {
	//         "jsonrpc": "2.0",
	//         "id": 1,
	//         "error": {
	//             "message": "Invalid params",
	//             "data": {
	//                 "reason": "invalid format",
	//                 "param": "nonce"
	//             },
	//             "code": -32602
	//         },
	//         "usIn": "1655391709417993",
	//         "usOut": "1655391709418049",
	//         "usDiff": 56,
	//         "testnet": false
	//     }
	//
	// subscribe
	//     {
	//         "jsonrpc": "2.0",
	//         "id": 2,
	//         "result": ["ticker.BTC_USDC-PERPETUAL.raw"],
	//         "usIn": "1655393625889396",
	//         "usOut": "1655393625889518",
	//         "usDiff": 122,
	//         "testnet": false
	//     }
	//
	// notification
	//     {
	//         "jsonrpc": "2.0",
	//         "method": "subscription",
	//         "params": {
	//             "channel": "ticker.BTC_USDC-PERPETUAL.raw",
	//             "data": {
	//                 "timestamp": 1655393724752,
	//                 "stats": [Object],
	//                 "state": "open",
	//                 "settlement_price": 21729.5891,
	//                 "open_interest": 164.501,
	//                 "min_price": 20792.9001,
	//                 "max_price": 21426.1864,
	//                 "mark_price": 21109.4757,
	//                 "last_price": 21132,
	//                 "instrument_name": "BTC_USDC-PERPETUAL",
	//                 "index_price": 21122.3937,
	//                 "funding_8h": -0.00022427,
	//                 "estimated_delivery_price": 21122.3937,
	//                 "current_funding": -0.00011158,
	//                 "best_bid_price": 21106,
	//                 "best_bid_amount": 1.143,
	//                 "best_ask_price": 21113,
	//                 "best_ask_amount": 0.402
	//             }
	//         }
	//     }
	//
	var error any = this.SafeValue(message, "error")
	if !ccxt.IsEqual(error, nil) {
		panic(ccxt.ExchangeError(this.Id + " " + this.Json(error)))
	}
	var params map[string]any = ccxt.SafeMapTyped(message, "params")
	var channel *string = this.SafeString(params, "channel")
	if channel != nil {
		var parts []string = strings.Split(*channel, ".")
		var channelId *string = this.SafeString(parts, 0)
		var userHandlers map[string]any = map[string]any{
			"trades":    this.HandleMyTrades,
			"portfolio": this.HandleBalance,
			"orders":    this.HandleOrders,
		}
		var handlers map[string]any = map[string]any{
			"ticker": this.HandleTicker,
			"quote":  this.HandleBidAsk,
			"book":   this.HandleOrderBook,
			"trades": this.HandleTrades,
			"chart":  this.HandleOHLCV,
			"user":   this.SafeValue(userHandlers, this.SafeString(parts, 1)),
		}
		var handler any = this.SafeValue(handlers, channelId)
		if !ccxt.IsEqual(handler, nil) {
			ccxt.CallDynamically(handler, client, message)
			return
		}
		panic(ccxt.NotSupported(this.Id + " no handler found for this message " + this.Json(message)))
	}
	var result map[string]any = ccxt.SafeMapTyped(message, "result")
	var accessToken *string = this.SafeString(result, "access_token")
	if accessToken != nil {
		this.HandleAuthenticationMessage(client, message)
	}
}
