func (this *Deribit) AuthenticateAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *Deribit) authenticateBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var url *string = ccxt.SafeStringPtr(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), "ws"))
	var client ccxt.ClientInterface = this.Client(url)
	var time int64 = this.Milliseconds()
	var timeString *string = this.NumberToString(time)
	var nonce *string = timeString
	var messageHash string = "authenticated"
	var future any = this.SafeValue(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash)
	if ccxt.IsEqual(future, nil) {
		this.CheckRequiredCredentials()
		var requestId int64 = this.RequestId()
		var lineBreak string = "\n" // eslint-disable-line quotes
		var signature string = this.Hmac(this.Encode(*timeString+lineBreak+*nonce+lineBreak), this.Encode(this.Secret), ccxt.Sha256)
		var request map[string]any = map[string]any{
			"jsonrpc": "2.0",
			"id":      requestId,
			"method":  "public/auth",
			"params": map[string]any{
				"grant_type": "client_signature",
				"client_id":  this.ApiKey,
				"timestamp":  time,
				"signature":  signature,
				"nonce":      nonce,
				"data":       "",
			},
		}

		future = (<-this.Watch(url, messageHash, this.Extend(request, params), messageHash))
		ccxt.PanicOnError(future)
		ccxt.AddElementToObject(client.(ccxt.ClientInterface).GetSubscriptions(), messageHash, future)
	}

	ch <- future
	return nil
}

func NewDeribit(userConfig map[string]any) *Deribit {
	p := newDeribit()
	p.Init(userConfig)
	return p
}

func (this *Deribit) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

